package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// pointThresholdsAt 把 thresholdsFile 指向临时目录里的一份配置，content 为
// 文件内容；测试结束自动还原。传空 content 且不建文件时用 pointAtMissing。
func writeThresholds(t *testing.T, content string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("写阈值配置文件失败：%v", err)
	}
	useThresholdsFile(t, path)
}

func useThresholdsFile(t *testing.T, path string) {
	t.Helper()
	previous := thresholdsFile
	thresholdsFile = path
	t.Cleanup(func() { thresholdsFile = previous })
}

func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20, "beijing": 3}`)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d，期望 20", got)
	}
	if got := LowStockThreshold("beijing"); got != 3 {
		t.Fatalf("LowStockThreshold(beijing) = %d，期望 3", got)
	}
	// 同一份文件里没配的仓库仍回退默认值。
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d，期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20, "beijing": 3}`)

