func writeThresholds(t *testing.T, content string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("写阈值配置文件失败：%v", err)
	}
	useThresholdsFile(t, path)
}

func useThresholdsFile(t *testing.T, path string) {
	t.Helper()
	previous := thresholdsFile
	thresholdsFile = path
	t.Cleanup(func() { thresholdsFile = previous })
}

func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20, "beijing": 3}`)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d，期望 20", got)
	}
	if got := LowStockThreshold("beijing"); got != 3 {
		t.Fatalf("LowStockThreshold(beijing) = %d，期望 3", got)
	}
	// 同一份文件里没配的仓库仍回退默认值。
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d，期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20, "beijing": 3}`)

	// 配置值高于默认值：10 低于 20，算低库存。
	if !IsLowStock("shanghai", 10) {
		t.Fatal("10 低于配置阈值 20，应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于配置阈值不算低库存（严格小于）")
	}
	// 配置值低于默认值：4 按默认值 5 会算低库存，按配置值 3 不算——证明配置覆盖默认值。
	if IsLowStock("beijing", 4) {
		t.Fatal("4 高于配置阈值 3，不应算低库存")
	}
	if !IsLowStock("beijing", 2) {
		t.Fatal("2 低于配置阈值 3，应当算低库存")
	}
}

func TestLowStockWarehousesUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20}`)

	got := LowStockWarehouses(map[string]int{"shanghai": 10, "chengdu": 10})
	want := []string{"shanghai"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v，期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v，期望 %v", got, want)
		}
	}
}

func TestMissingThresholdsFileFallsBackToDefault(t *testing.T) {
	// 临时目录里不创建配置文件。
	useThresholdsFile(t, filepath.Join(t.TempDir(), "thresholds.json"))

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件缺失时 LowStockThreshold(shanghai) = %d，期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestMalformedThresholdsFileFallsBackToDefault(t *testing.T) {
	writeThresholds(t, `{"shanghai": `)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件损坏时 LowStockThreshold(shanghai) = %d，期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

